audio-fingerprinting.pseudocode:
def fingerprints(peaks, fan_out=5):
    # peaks: (시각, 주파수) 목록, 시각순 정렬
    out = []
    for i, (t1, f1) in enumerate(peaks):
        for t2, f2 in peaks[i + 1:i + 1 + fan_out]:
            h = (f1, f2, t2 - t1)  # 앵커-타깃 쌍 해시
            out.append((h, t1))
    return out

def match(query_fp, db):  # db: 해시 → [(곡ID, 시각)]
    votes = {}
    for h, tq in query_fp:
        for song, ts in db.get(h, []):
            key = (song, ts - tq)  # 오프셋이 일정 = 같은 곡
            votes[key] = votes.get(key, 0) + 1
    if not votes:
        return None
    return max(votes, key=votes.get)[0]

audit-log.pseudocode:
def append_log(log, event):
    prev = log[-1]['hash'] if log else '0' * 64
    h = sha256(prev + serialize(event))  # 이전 해시와 연결
    log.append({'event': event, 'prev': prev, 'hash': h})

def verify_log(log):
    prev = '0' * 64
    for i, rec in enumerate(log):
        expect = sha256(prev + serialize(rec['event']))
        if rec['prev'] != prev or rec['hash'] != expect:
            return i  # 이 위치부터 위변조·삭제 의심
        prev = rec['hash']
    return None  # 체인 무결

auto-scaling.pseudocode:
def desired_replicas(current, metric, target,
                     lo, hi, tolerance=0.1):
    # 쿠버네티스 HPA 방식: 현재값/목표값 비율로 조정
    ratio = metric / target
    if abs(ratio - 1.0) <= tolerance:
        return current  # 허용 오차 내면 유지(진동 방지)
    desired = ceil(current * ratio)
    return max(lo, min(hi, desired))  # 최소·최대 범위

# 예: 4대, CPU 90% / 목표 60% → ceil(4 × 1.5) = 6대

automatic-differentiation.pseudocode:
class Var:  # 후진 모드 자동 미분
    def __init__(self, value, parents=()):
        self.value, self.grad = value, 0.0
        self.parents = parents  # (부모, 국소 미분값)
    def __add__(self, o):
        return Var(self.value + o.value,
                   ((self, 1.0), (o, 1.0)))
    def __mul__(self, o):
        return Var(self.value * o.value,
                   ((self, o.value), (o, self.value)))

def backward(out):
    order, seen = [], set()
    def topo(v):  # 연산 그래프 위상 정렬
        if id(v) not in seen:
            seen.add(id(v))
            for p, _ in v.parents:
                topo(p)
            order.append(v)
    topo(out)
    out.grad = 1.0
    for v in reversed(order):  # 출력에서 입력 방향으로
        for p, local in v.parents:
            p.grad += v.grad * local  # 연쇄법칙 누적

automatic-repeat-request.pseudocode:
def go_back_n(frames, N, send, wait):
    # send(seq, frame): 전송
    # wait(): ('ack', n) 또는 ('timeout', None)
    base = next_seq = 0
    while base < len(frames):
        # 윈도우(크기 N) 안의 미전송 프레임 송신
        while next_seq < min(base + N, len(frames)):
            send(next_seq, frames[next_seq])
            next_seq += 1
        ev, ack = wait()  # base 프레임 타이머 기준
        if ev == 'ack' and ack >= base:
            base = ack + 1  # 누적 ACK: ack까지 수신 확인
        elif ev == 'timeout':
            next_seq = base  # base부터 전부 재전송
